const headerLinks = ['About Us', 'Request a demo', 'Buy Subscription', 'Career', 'Blog'];
headerLinks.forEach(text => {
  cy.contains('a', text).should('exist').and('be.visible').and('have.attr', 'href').and('not.be.empty');
});

const footerLinks = ['Contact Us', 'Terms & Conditions', 'Privacy Policy', 'Refund Policy'];
footerLinks.forEach(text => {
  cy.contains('footer a, a', text).last() // in case both inline and footer versions match, target footer instance
  .should('exist').and('be.visible').and('have.attr', 'href').and('not.be.empty');
});

cy.get('a').should('have.length.greaterThan', 0);
cy.get('a').each($link => {
  const href = $link.attr('href');
  const text = $link.text().trim() || '(no text)';
  // Skip links with no href (e.g., JS-only buttons styled as <a>)
  if (href === undefined) {
    cy.log(`SKIPPED (no href): "${text}"`);
    return;
  }
  expect(href, `href for "${text}"`).to.not.be.empty;
  cy.log(`Link "${text}" -> ${href}`);
});

cy.get('a').then($links => {
  const hrefs = [...new Set($links.map((i, el) => Cypress.$(el).attr('href')).get().filter(href => href && href.startsWith('http') && !href.startsWith('mailto:') && !href.startsWith('tel:')))];
  hrefs.forEach(href => {
    cy.request({
      url: href,
      failOnStatusCode: false
    }).then(resp => {
      cy.log(`${href} -> status ${resp.status}`);
      expect(resp.status, `Status for ${href}`).to.be.lessThan(400);
    });
  });
});
